/* Formats a signed % with a +/- sign, e.g. "+12.3%" / "-44.8%" */
export const fmtPct = (n) => (n === null || n === undefined || isNaN(n))
  ? '—'
  : (n >= 0 ? '+' : '') + n.toLocaleString('de-DE', {minimumFractionDigits:1, maximumFractionDigits:1}) + '%';

